<section class="page-hero compact"><p class="eyebrow">THE ARCHON LIBRARY</p><h1>eBooks to live <em>with.</em></h1></section><section class="section shop"><form class="filters filters-wide" method="get"><input name="q" value="<?=Security::e($q)?>" placeholder="Title, author, ISBN"><select name="category"><option value="">All categories</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=$category==$c['id']?'selected':''?>><?=Security::e($c['name'])?></option><?php endforeach;?></select><select name="genre"><option value="">All genres</option><?php foreach($genres as $g):?><option value="<?=$g['id']?>" <?=$genre==$g['id']?'selected':''?>><?=Security::e($g['name'])?></option><?php endforeach;?></select><select name="author"><option value="">All authors</option><?php foreach($authors as $a):?><option value="<?=$a['id']?>" <?=$author==$a['id']?'selected':''?>><?=Security::e($a['name'])?></option><?php endforeach;?></select><select name="language"><option value="">All languages</option><?php foreach($languages as $item):?><option value="<?=Security::e($item['language'])?>" <?=$language===$item['language']?'selected':''?>><?=Security::e($item['language'])?></option><?php endforeach;?></select><input name="min" value="<?=Security::e($min)?>" type="number" min="0" step=".01" placeholder="Min price"><input name="max" value="<?=Security::e($max)?>" type="number" min="0" step=".01" placeholder="Max price"><select name="sort"><option value="newest">Newest</option><option value="popular" <?=$sort==='popular'?'selected':''?>>Popular</option><option value="price" <?=$sort==='price'?'selected':''?>>Price</option><option value="rating" <?=$sort==='rating'?'selected':''?>>Rating</option></select><label class="filter-check"><input type="checkbox" name="free" value="1" <?=$free?'checked':''?>> Free</label><label class="filter-check"><input type="checkbox" name="sale" value="1" <?=$sale?'checked':''?>> On sale</label><button>Filter</button><a href="/ebooks">Clear</a></form><p class="result-count"><?=$count?> title<?=$count===1?'':'s'?> found</p><div class="book-grid"><?php foreach($books as $book):require __DIR__.'/../components/book-card.php';endforeach;?></div><?php if(!$books):?><div class="empty"><h2>No titles found</h2><p>Try removing a filter or searching another term.</p><a class="button" href="/ebooks">Browse all eBooks</a></div><?php endif;?><?php if($pages>1):?><nav class="pagination" aria-label="Catalogue pages"><?php for($n=1;$n<=$pages;$n++):?><a class="<?=$n===$page?'current':''?>" href="?<?=http_build_query(array_merge($_GET,['page'=>$n]))?>"><?=$n?></a><?php endfor;?></nav><?php endif;?></section>
